-- =====================================================================
-- Adds first / middle / last name of the voter and of the father / husband / mother (computed by the
-- database from the name: nothing to fill in, always in step with the name) to an existing database.
-- The application also adds them automatically on the first page load after the update; run this only
-- if you prefer to do it yourself (phpMyAdmin > your database > Import). Safe to run more than once.
-- =====================================================================
SET @have := (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'voters' AND column_name = 'first_name');
SET @sql := IF(@have = 0, 'ALTER TABLE voters ADD COLUMN first_name VARCHAR(120) GENERATED ALWAYS AS (case when name is null or trim(replace(replace(replace(name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')) = '''' then null else substring_index(trim(replace(replace(replace(name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), '' '', 1) end) VIRTUAL', 'SELECT 1');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @have := (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'voters' AND column_name = 'middle_name');
SET @sql := IF(@have = 0, 'ALTER TABLE voters ADD COLUMN middle_name VARCHAR(120) GENERATED ALWAYS AS (case when name is null or (char_length(trim(replace(replace(replace(name, ''    '', '' ''), ''  '', '' ''), ''  '', '' ''))) - char_length(replace(trim(replace(replace(replace(name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), '' '', ''''))) < 2 then null else trim(substring(trim(replace(replace(replace(name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), char_length(substring_index(trim(replace(replace(replace(name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), '' '', 1)) + 2, char_length(trim(replace(replace(replace(name, ''    '', '' ''), ''  '', '' ''), ''  '', '' ''))) - char_length(substring_index(trim(replace(replace(replace(name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), '' '', 1)) - char_length(substring_index(trim(replace(replace(replace(name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), '' '', -1)) - 2)) end) VIRTUAL', 'SELECT 1');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
