PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @have := (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'voters' AND column_name = 'relative_first_name');
SET @sql := IF(@have = 0, 'ALTER TABLE voters ADD COLUMN relative_first_name VARCHAR(120) GENERATED ALWAYS AS (case when relative_name is null or trim(replace(replace(replace(relative_name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')) = '''' then null else substring_index(trim(replace(replace(replace(relative_name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), '' '', 1) end) VIRTUAL', 'SELECT 1');
