SET @sql := IF(@have = 0, 'ALTER TABLE voters ADD COLUMN relative_middle_name VARCHAR(120) GENERATED ALWAYS AS (case when relative_name is null or (char_length(trim(replace(replace(replace(relative_name, ''    '', '' ''), ''  '', '' ''), ''  '', '' ''))) - char_length(replace(trim(replace(replace(replace(relative_name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), '' '', ''''))) < 2 then null else trim(substring(trim(replace(replace(replace(relative_name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), char_length(substring_index(trim(replace(replace(replace(relative_name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), '' '', 1)) + 2, char_length(trim(replace(replace(replace(relative_name, ''    '', '' ''), ''  '', '' ''), ''  '', '' ''))) - char_length(substring_index(trim(replace(replace(replace(relative_name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), '' '', 1)) - char_length(substring_index(trim(replace(replace(replace(relative_name, ''    '', '' ''), ''  '', '' ''), ''  '', '' '')), '' '', -1)) - 2)) end) VIRTUAL', 'SELECT 1');
